     "kind": "type",
     "signature": "export type Rows implements Iterable<Row>",
     "doc": "`for row in rows(ref stmt)` over the remaining rows of a statement.\n\n`Iterable.next` has no error channel, so a mid-iteration sqlite failure ends\nthe loop and is recorded in `err`. CHECK `err` AFTER THE LOOP if you need to\ntell \"no more rows\" from \"the query broke\" - an empty `err` means the former.\n(Same trade std/fs.yoop's DirIter makes.)\n\nNot Disposable: it borrows the statement, which the caller still owns.",
     "shape": "export type Rows implements Iterable<Row> {\n    raw: RawStmt,\n    db: RawDb,\n    err: string,\n    done: bool,\n\n    function next(ref self): IterStep<Row> {\n        if (self.done) { return IterStep.Done; }\n        let rc: int32 = rawStep(self.raw);\n        if (rc == SQLITE_ROW) {\n            return IterStep.Yield { value: { raw: self.raw } };\n        }\n        self.done = true;\n        if (rc != SQLITE_DONE) {\n            self.err = `sqlite: step failed: ${rawErrmsg(self.db)}`;\n        }\n        return IterStep.Done;\n    }\n}",
