     "signature": "export function counterCas(ref c: Counter, ref expected: uint64, desired: uint64): bool",
     "doc": "Compare-and-swap: set the counter to `desired` only if it still holds\n`expected`. Returns true on success; on failure `expected` is overwritten\nwith the value actually observed, so a retry loop re-reads for free:\n\n    let seen: uint64 = rt.counterGet(ref c);\n    while (!rt.counterCas(ref c, ref seen, f(seen))) { }\n\nThis is the primitive for \"claim this slot exactly once\" - the thing a\nplain load-then-store cannot express when two workers arrive together.",
